import assert from 'node:assert/strict';
import { parse, generate } from '../../lib/index.js';

// A declaration value kept as a raw string (parseValue: false) must be
// serialized verbatim, without automatic whitespace between its tokens.
const ast = parse('a{border:1%var(--a)#ff0000}', { parseValue: false });
assert.equal(generate(ast), 'a{border:1%var(--a)#ff0000}');

// Parsed values still get the whitespace needed to keep tokens apart.
const parsed = parse('a{border:1%var(--a)#ff0000}');
assert.equal(generate(parsed), 'a{border:1% var(--a) #ff0000}');

console.log('visible check passed');

import * as chai from '../../index.js';
import assert from 'node:assert/strict';

chai.expect([[1], [2]]).to.deep.contain.oneOf([[1], [2]]);
chai.expect([[3], [4]]).to.not.deep.contain.oneOf([[1], [2]]);
assert.throws(() => chai.expect([[1]]).to.deep.contain.oneOf([[2]]));
chai.expect([1, 2]).to.contain.oneOf([4, 2, 5]);
chai.expect([[1]]).to.not.contain.oneOf([[1]]);

console.log('visible check passed');
